# Let me check if the MCP server is configured
import json, os, glob

# Look for settings.json
for path in ['/tmp', os.path.expanduser('~/.prime'), '/root/.prime']:
    for root, dirs, files in os.walk(path):
        for f in files:
            if f == 'settings.json':
                full = os.path.join(root, f)
                print(f"Found: {full}")
                try:
                    with open(full) as fh:
                        data = json.load(fh)
                    if 'mcp' in str(data).lower() or 'nethack' in str(data).lower():
                        print(json.dumps(data, indent=2)[:500])
                except:
                    pass
"}

