# The manual HTTP approach works. Let me create a reusable helper.
import httpx
import json

MCP_URL = "http://127.0.0.1:44841/mcp"

async def game_call(tool_name, **kwargs):
    """Call a nethack MCP tool directly via HTTP."""
    payload = {
        "jsonrpc": "2.0",
        "method": "tools/call",
        "id": 1,
        "params": {
            "name": tool_name,
            "arguments": kwargs if kwargs else {}
        }
    }
    headers = {
        "Content-Type": "application/json",
        "Accept": "application/json, text/event-stream",
    }
    async with httpx.AsyncClient() as client:
        resp = await client.post(MCP_URL, json=payload, headers=headers, timeout=120)
        data = resp.json()
        if "result" in data and "content" in data["result"]:
            for item in data["result"]["content"]:
                if item["type"] == "text":
                    return item["text"]
        return json.dumps(data, indent=2)

# Let me reveal the full map first (this doesn't consume a turn)
result = await game_call("reveal", x1=0, y1=0, x2=78, y2=20)
print(result)
"}

